import "server-only";

function normalizeOrigin(value: string | undefined | null) {
  if (!value) return null;

  try {
    const url = new URL(
      value.startsWith("http://") || value.startsWith("https://")
        ? value
        : `https://${value}`,
    );
    return url.origin;
  } catch {
    return null;
  }
}

/**
 * Canonical application origin used for links generated by server code.
 * Explicit SITE_URL wins. On Vercel, the stable production project URL is a
 * safe fallback so the first deployment can register/reset accounts before a
 * custom domain is attached.
 */
export function configuredSiteOrigin() {
  const candidates = [
    process.env.SITE_URL,
    process.env.NEXT_PUBLIC_SITE_URL,
    process.env.VERCEL === "1" && process.env.VERCEL_PROJECT_PRODUCTION_URL
      ? `https://${process.env.VERCEL_PROJECT_PRODUCTION_URL}`
      : undefined,
  ];

  for (const candidate of candidates) {
    const origin = normalizeOrigin(candidate);
    if (!origin) continue;
    if (process.env.NODE_ENV === "production" && !origin.startsWith("https://")) {
      continue;
    }
    return origin;
  }

  return null;
}

export function normalizeRequestOrigin(value: string | undefined | null) {
  return normalizeOrigin(value);
}
